function auditAliasCohort(data) {
 const {observations, setups, analyses}=data, failures=[];
 const check=(ok,label)=>{if(!ok)failures.push(label);};
 const eq=(a,b)=>JSON.stringify(a)===JSON.stringify(b);
 const median=values=>{const v=[...values].sort((a,b)=>a-b),n=v.length;return n%2?v[(n-1)/2]:(v[n/2-1]+v[n/2])/2;};
 const sum=v=>v.reduce((a,b)=>a+b,0);
 const q=(v,p)=>{const i=(v.length-1)*p,l=Math.floor(i),h=Math.ceil(i);return v[l]+(v[h]-v[l])*(i-l);};
 const near=(a,b)=>Number.isFinite(a)&&Number.isFinite(b)&&Math.abs(a-b)<=1e-9;
 const orders=["ABC","BCA","CAB","ACB","CBA","BAC","ABC","BCA","CAB","ACB","CBA","BAC"];
 const groupIds=[0,1,2,87,91,92,105,123,126,139], promoted=[1,87,91,92,105,123,126,139];
 check(observations.length===36,"exactly 36 observations"); check(setups.length===1,"one setup"); check(analyses.length===1,"one analysis");
 const setup=setups[0], a=analyses[0];
 check(setup.complete===true&&setup.failure===null,"setup completed");
 check(setup.node==="v22.22.0","pinned Node22");
 check(setup.researchBinding.commit==="d0a79f888b36684f26ca76ef880c019ad06c88f1","exact research commit");
 check(setup.researchBinding.githubSha===setup.researchBinding.commit,"Actions SHA binding");
 check(setup.protocolSha256==="bed962679c7b0b86d96d9ebcd1c47d62a8f667ed05afe8828b7c1d0399f6f962","frozen protocol hash");
 check(setup.researchBinding.protocolBlob==="83930b97ad2fc05697dbf83455229fe148962010","frozen protocol blob");
 check(eq(setup.researchBinding,a.researchBinding),"setup/analysis research binding");
 check(eq(setup.preAcquisitionBinding.sourceHashes,a.sourceHashes),"source hashes before/final");
 check(eq(setup.preAcquisitionBinding.harnessHashes,a.harnessHashes),"harness hashes before/final");
 check(setup.capture.manifestSha256===a.captureManifestSha256,"capture manifest");
 check(setup.capture.seedSha256==="f50a48e23056054a13f90dfa7aad53ba3a80a6f6e7125289a5ad52dc2f9f686e","canonical seed");
 check(eq(setup.capture.groups,groupIds)&&setup.capture.rows===400000,"captured groups/rows");
 const blocks=Array.from({length:12},(_,block)=>({block,order:orders[block]}));
 const physical={A:new Set(),B:new Set(),C:new Set()};
 const byOrdinal=[...observations].sort((x,y)=>x.ordinal-y.ordinal);
 for(let i=0;i<byOrdinal.length;i++){
  const o=byOrdinal[i], b=Math.floor(i/3),arm=orders[b][i%3];
  check(o.ordinal===i&&o.block===b&&o.arm===arm,"schedule "+i);
  check(o.complete===true,"complete "+i);
  check(Number.isFinite(o.elapsedMs)&&o.elapsedMs>0&&near(Number(o.elapsedNs)/1e6,o.elapsedMs),"elapsed clock "+i);
  check(o.inputWitnessBefore===a.inputWitnessSha256&&o.inputWitnessAfter===a.inputWitnessSha256,"input immutability "+i);
  for(const k of ["failures","cleanupFailures","workerFailures"])check(Array.isArray(o[k])&&o[k].length===0,k+" "+i);
  const qu=o.postFinalizationQuiescence;
  check(qu.parentOpenResources===0&&qu.lockEntries.length===0&&qu.stagingEntries.length===0,"quiescence "+i);
  check(o.workerTransports.length===5&&o.workerTransports.filter(w=>w.kind==="compression").length===4&&o.workerTransports.filter(w=>w.kind==="index").length===1,"worker set "+i);
  check(o.workerTransports.every(w=>w.readySeen===true&&w.failures.length===0),"worker readiness/drain "+i);
  check(o.workerTransports.filter(w=>w.kind==="compression").every(w=>w.messages===0),"tiny alias owner-thread compression "+i);
  check(eq(o.groupElapsedNs.map(g=>g.group),groupIds),"group schedule "+i);
  check(sum(o.groupElapsedNs.map(g=>Number(g.elapsedNs)))<=Number(o.elapsedNs),"group clock coverage "+i);
  check(eq(o.groupElapsedNs.filter(g=>g.promoted).map(g=>g.group),arm==="B"?promoted:[]),"promotion route "+i);
  check(sum(o.groupElapsedNs.map(g=>g.rawRows))===(arm==="B"?175:0),"promoted row count "+i);
  const v=o.verification;
  check(v.verifiedRows===400000&&v.lookupProbes===84&&v.referencedCanonicalDefinitions===9302,"verification counts "+i);
  check(v.logicalSha256===a.logicalSha256,"logical equality "+i);
  check(eq(v.promotedGroups,arm==="B"?promoted:[]),"verification promoted groups "+i);
  const sizes={descriptorBytes:64,indexBytes:arm==="B"?24232348:24663588,lookupPayloadBytes:arm==="B"?21031588:21461412,affectedPayloadBytes:arm==="B"?16876960:17306784,addedContentBytes:arm==="B"?2260:0};
  for(const [k,value]of Object.entries(sizes))check(v[k]===value,"size "+k+" "+i);
  physical[arm].add(v.normalizedPhysicalSha256);
  check(o.contentFinalization.persistedLengthAfterClose===7533449+sizes.addedContentBytes&&o.contentFinalization.logicalLengthAfterClose===7533449+sizes.addedContentBytes,"final content length "+i);
  check(Number.isFinite(o.recordFinalization.totalMs)&&Number.isFinite(o.contentFinalization.totalMs),"both finalization receipts "+i);
  blocks[b][arm]=o.elapsedMs;
 }
 check(Object.values(physical).every(s=>s.size===1),"arm-specific stable physical hashes");
 check([...physical.A][0]===[...physical.C][0],"identical-code physical equality");
 for(const arm of ["A","B","C"])check([...physical[arm]][0]===a.physicalHashes[arm],"declared physical hash "+arm);
 const comparisons={};
 for(const control of ["A","C"]){
  const key="B/"+control,dms=blocks.map(r=>r.B-r[control]),dp=blocks.map(r=>(r.B/r[control]-1)*100);
  comparisons[key]={differencesMs:dms,differencesPercent:dp,medianDifferenceMs:median(dms),medianDifferencePercent:median(dp),fasterPairs:dms.filter(x=>x<0).length,candidateTotalMs:sum(blocks.map(r=>r.B)),controlTotalMs:sum(blocks.map(r=>r[control]))};
  comparisons[key].equalWorkChangePercent=(comparisons[key].candidateTotalMs/comparisons[key].controlTotalMs-1)*100;
 }
 let state=0x000da6c4;
 const metrics=[comparisons["B/A"].differencesMs,comparisons["B/A"].differencesPercent,comparisons["B/C"].differencesMs,comparisons["B/C"].differencesPercent];
 const distributions=metrics.map(()=>[]);
 for(let repeat=0;repeat<20000;repeat++){
  const sample=[];
  for(let j=0;j<12;j++){state^=state<<13;state^=state>>>17;state^=state<<5;state>>>=0;sample.push(Math.floor((state/4294967296)*12));}
  for(let j=0;j<4;j++)distributions[j].push(median(sample.map(i=>metrics[j][i])));
 }
 const intervals=distributions.map(v=>{v.sort((x,y)=>x-y);return [q(v,.025),q(v,.975)];});
 for(let i=0;i<2;i++){
  const key=i===0?"B/A":"B/C", c=comparisons[key], original=a.comparisons[key];
  c.medianDifferenceMs95=intervals[i*2];c.medianDifferencePercent95=intervals[i*2+1];
  c.mechanicalGate=c.medianDifferenceMs<=-10&&c.medianDifferencePercent<=-10&&c.fasterPairs>=9&&c.candidateTotalMs<c.controlTotalMs&&c.medianDifferenceMs95[1]<0&&c.medianDifferencePercent95[1]<0;
  check(near(c.medianDifferenceMs,-original.pairedMedianSavingMs),"reported median ms "+key);
  check(near(c.medianDifferencePercent,-original.pairedMedianSavingPercent),"reported median percent "+key);
  check(c.fasterPairs===original.fasterPairs,"reported faster count "+key);
  check(near(c.equalWorkChangePercent,original.equalWorkChangePercent),"reported equal work "+key);
  for(let j=0;j<2;j++){check(near(c.medianDifferenceMs95[j],original.pairedMedianDifferenceMs95[j]),"reported ms interval "+key+j);check(near(c.medianDifferencePercent95[j],original.pairedMedianDifferencePercent95[j]),"reported pct interval "+key+j);}
 }
 const ca=blocks.map(r=>(r.C/r.A-1)*100),controlMedian=median(ca),driftLimit=Math.min(-comparisons["B/A"].medianDifferencePercent,-comparisons["B/C"].medianDifferencePercent)/2;
 check(near(controlMedian,a.control.pairedMedianPercent),"reported control median"); check(state===a.bootstrap.finalState,"shared bootstrap stream final state");
 const advance=failures.length===0&&comparisons["B/A"].mechanicalGate&&comparisons["B/C"].mechanicalGate&&Math.abs(controlMedian)<driftLimit;
 return {schemaVersion:1,independentEvaluator:"Reimplemented from frozen protocol; did not call production cohort evaluator",completeObservations:observations.length,blocks,failures,comparisons,control:{pairedMedianPercent:controlMedian,maximumAbsolutePercentExclusive:driftLimit,pass:Math.abs(controlMedian)<driftLimit},bootstrap:{samples:20000,seedHex:"0x000da6c4",finalState:state,percentile:"type7",sharedWholeBlockDraws:true},advance,protocolBlob:setup.researchBinding.protocolBlob,researchBinding:setup.researchBinding,sourceHashChecks:"Compared exact setup pre-acquisition and final analysis hash maps; did not independently hash unavailable remote binary files",semanticCheckScope:"Checked every printed verification, ownership/quiescence, route and source-identity receipt; no independent reread of lost binary capture/OPFS graphs",artifactLimitation:"Actions upload failed on a vertical-bar OPFS filename after all36 observations and analysis; full decoded log and compact receipts retained by baseline_profile, but binary graphs and OPFS outputs are not claimed retained",claimScope:"Immutable completed-content-tail Node record-sink component. Advance only to private ownership design and separate browser qualification; not a whole-import gain."};
}
